  ('bulugh_almaram', 123, 'مُتَّفَقٌ عَلَيْهِ، زَادَ ابْنُ حِبَّانَ: «وَتَلْتَقِي».'),
  ('bulugh_almaram', 124, 'رَوَاهُ أَبُو دَاوُدَ، وَالتِّرْمِذِيُّ وَضَعَّفَاهُ.'),
  ('bulugh_almaram', 129, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِمُسْلِمٍ، وَفِي رِوَايَةٍ لِلْبُخَارِيِّ: وَضَرَبَ بِكَفَّيْهِ الأَرْضَ، وَنَفَخَ فِيهِمَا، ثُمَّ مَسَحَ بِهِمَا وَجْهَهُ وَكَفَّيْهِ.'),
  ('bulugh_almaram', 130, 'رَوَاهُ الدَّارَقُطْنِيُّ، وَصَحَّحَ الْأَئِمَّةُ وَقْفَهُ.'),
  ('bulugh_almaram', 131, 'رَوَاهُ الْبَزَّارُ، وَصَحَّحَهُ ابْنُ الْقَطَّانِ، ولَكِنْ صَوَّبَ الدَّارَقُطْنِيُّ إِرْسَالَهُ.'),
  ('bulugh_almaram', 133, 'رَوَاهُ أَبُو دَاوُدَ والنَّسَائِيُّ.'),
  ('bulugh_almaram', 134, 'رَوَاهُ الدَّارَقُطْنِيُّ مَوْقُوفًا، وَرَفَعَهُ الْبَزَّارُ، وَصَحَّحَهُ ابْنُ خُزَيْمَةَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 135, 'رَوَاهُ ابْنُ مَاجَه بِسَنَدٍ وَاهٍ جِدًَّا.'),
  ('bulugh_almaram', 136, 'رَوَاهُ أَبُو دَاوُدَ بِسَنَدٍ فِيهِ ضَعْفٌ، وَفِيهِ اخْتِلَافٌ عَلَى رُوَاتِهِ.'),
  ('bulugh_almaram', 137, 'رَوَاهُ الدَّارَقُطْنِيُّ بِإِسْنَادٍ ضَعِيفٍ جِدًّا.'),
  ('bulugh_almaram', 138, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالْحَاكِمُ، وَاسْتَنْكَرَهُ أَبُو حَاتِمٍ.'),
  ('bulugh_almaram', 140, 'رَوَاهُ الْخَمْسَةُ إِلَّا النَّسَائِيَّ، وَصَحَّحَهُ التِّرْمِذِيُّ، وَحَسَّنَهُ الْبُخَارِيُّ.'),
