  ('bulugh_almaram', 783, 'رَوَاهُ الْخَمْسَةُ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 784, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 785, 'مُتَّفَقٌ عَلَيْهِ، وَهَذَا السِّيَاقُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 786, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 787, 'رَوَاهُ الْبُخَارِيُّ، وَزَادَ أَحْمَدُ وَالنَّسَائِيُّ: فِي سَمْنٍ جَامِدٍ.'),
  ('bulugh_almaram', 788, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ، وَقَدْ حَكَمَ عَلَيْهِ البُخَارِيُّ وَأَبُو حَاتِمٍ بِالْوَهْمِ.'),
  ('bulugh_almaram', 789, 'رَوَاهُ مُسْلِمٌ، وَالنَّسَائِيُّ وَزَادَ: إِلَّا كَلْبَ صَيْدٍ.'),
  ('bulugh_almaram', 790, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِلْبُخَارِيِّ، وَعِنْدَ مُسْلِمٍ: فَقَالَ: «اشْتَرِيهَا وَأَعْتِقِيهَا وَاشْتَرِطِي لَهُمُ الْوَلَاءَ».'),
  ('bulugh_almaram', 791, 'رَوَاهُ مَالِكٌ وَالْبَيْهَقِيُّ، وَقَالَ: رَفَعَهُ بَعْضُ الرُّوَاةِ، فَوَهِمَ.'),
  ('bulugh_almaram', 792, 'رَوَاهُ النَّسَائِيُّ وَابْنُ مَاجَهْ وَالدَّارَقُطْنِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 793, 'رَوَاهُ مُسْلِمٌ، وَزَادَ فِي رِوَايَةٍ: وَعَنْ بَيْعِ ضِرَابِ الْجَمَلِ.'),
  ('bulugh_almaram', 794, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 795, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِلْبُخَارِيِّ.'),
  ('bulugh_almaram', 796, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 797, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 798, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 799, 'رَوَاهُ أَحْمَدُ وَالنَّسَائِيُّ، وَصَحَّحَهُ التِّرْمِذِيُّ وَابْنُ حِبَّانَ، وَلِأَبِي دَاوُدَ: «مَنْ بَاعَ بَيْعَتَيْنِ فِي بَيْعَةٍ فَلَهُ أَوَكَسُهُمَا، أَوِ الرِّبَا».'),
  ('bulugh_almaram', 800, 'أَخْرَجَهُ الطَّبَرَانِيُّ فِي «الْأَوْسَطِ» وَهُوَ غَرِيبٌ.'),
  ('bulugh_almaram', 801, 'رَوَاهُ مَالِكٌ، قَالَ: بَلَغَنِي عَنْ عَمْرِو بْنِ شُعَيْبٍ، بِهِ.'),
  ('bulugh_almaram', 802, 'رَوَاهُ أَحْمَدُ، وَأَبُو دَاوُدَ وَاللَّفْظُ لَهُ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 803, 'رَوَاهُ الْخَمْسَةُ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 804, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 805, 'رَوَاهُ الْخَمْسَةُ إِلَّا ابْنَ مَاجَهْ، وَصَحَّحَهُ التِّرْمِذِيُّ.'),
  ('bulugh_almaram', 806, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 807, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِلْبُخَارِيِّ.'),
  ('bulugh_almaram', 808, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 809, 'مُتَّفَقٌ عَلَيْهِ، وَلِمُسْلِمٍ: «لَا يَسُمِ الْمُسْلِمُ عَلَى سَوْمِ الْمُسْلِمِ».'),
  ('bulugh_almaram', 810, 'رَوَاهُ أَحْمَدُ، وَصَحَّحَهُ التِّرْمِذِيُّ وَالْحَاكِمُ، وَلَكِنْ فِي إِسْنَادِهِ مَقَالٌ، وَلَهُ شَاهِدٌ.'),
  ('bulugh_almaram', 811, 'رَوَاهُ أَحْمَدُ، وَرِجَالُهُ ثِقَاتٌ، وَقَدْ صَحَّحَهُ ابْنُ خُزَيْمَةَ وَابْنُ الْجَارُودِ وَابْنُ حِبَّانَ وَالْحَاكِمُ وَالطَّبَرَانِيُّ وَابْنُ الْقَطَّانِ.'),
  ('bulugh_almaram', 812, 'رَوَاهُ الْخَمْسَةُ إِلَّا النَّسَائِيَّ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 813, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 814, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 815, 'رَوَاهُ الْبُخَارِيُّ، وَزَادَ الْإِسْمَاعِيلِيُّ: مِنْ تَمْرٍ.'),
  ('bulugh_almaram', 816, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 817, 'رَوَاهُ الطَّبَرَانِيُّ فِي «الْأَوْسَطِ» بِإِسْنَادٍ حَسَنٍ.'),
  ('bulugh_almaram', 818, 'رَوَاهُ الْخَمْسَةُ، وَضَعَّفَهُ الْبُخَارِيُّ وَأَبُو دَاوُدَ، وَصَحَّحَهُ التِّرْمِذِيُّ وَابْنُ خُزَيْمَةَ وَابْنُ الْجَارُودِ وَابْنُ حِبَّانَ وَالْحَاكِمُ وَابْنُ الْقَطَّانِ.'),
  ('bulugh_almaram', 819, 'أَخْرَجَهُ الْبُخَارِيُّ ضِمْنَ حَدِيثٍ، وَلَمْ يَسُقْ لَفْظَهُ.'),
  ('bulugh_almaram', 821, 'رَوَاهُ ابْنُ مَاجَهْ وَالْبَزَّارُ وَالدَّارَقُطْنِيُّ بِإِسْنَادٍ ضَعِيفٍ.'),
  ('bulugh_almaram', 822, 'رَوَاهُ أَحْمَدُ، وَأَشَارَ إِلَى أَنَّ الصَّوَابَ وَقْفُهُ.'),
  ('bulugh_almaram', 823, 'أَخْرَجَهُ أَيْضًا مَوْقُوفًا عَلَى ابْنِ عَبَّاسٍ بِإِسْنَادٍ قَوِيٍّ، وَرَجَّحَهُ الْبَيْهَقِيُّ.'),
  ('bulugh_almaram', 824, 'رَوَاهُ الْبَزَّارُ، وَفِي إِسْنَادِه ضَعْفٌ.'),
  ('bulugh_almaram', 825, 'رَوَاهُ أَبُو دَاوُدَ وَابْنُ مَاجَهْ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 826, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 827, 'رَوَاهُ الْخَمْسَةُ إِلَّا ابْنَ مَاجَهْ، وَالدَّارَقُطْنِيُّ وَابْنُ خُزَيْمَةَ وَابْنُ الْجَارُودِ، وَفِي رِوَايَةٍ: «حَتَّى يَتَفَرَّقَا مِنْ مَكَانِهِمَا».'),
  ('bulugh_almaram', 828, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 829, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 831, 'رَوَاهُ ابْنُ مَاجَهْ مُخْتَصَرًا، وَالْحَاكِمُ بِتَمَامِهِ وَصَحَّحَهُ.'),
  ('bulugh_almaram', 832, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 833, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 834, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 835, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 836, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 837, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 838, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 839, 'رَوَاهُ الْخَمْسَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ وَابْنُ الْجَارُودِ.'),
  ('bulugh_almaram', 840, 'رَوَاهُ الْحَاكِمُ وَالْبَيْهَقِيُّ، وَرِجَالُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 841, 'رَوَاهُ أَبُو دَاوُدَ مِنْ رِوَايَةِ نَافِعٍ عَنْهُ، وَفِي إِسْنَادِهِ مَقَالٌ، وَلِأَحْمَدَ: نَحْوُهُ مِنْ رِوَايَةِ عَطَاءٍ، وَرِجَالُهُ ثِقَاتٌ وَصَحَّحَهُ ابْنُ الْقَطَّانِ.'),
  ('bulugh_almaram', 842, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ، وَفِي إِسْنَادِهِ مَقَالٌ.'),
  ('bulugh_almaram', 843, 'رَوَاهُ أَبُو دَاوُدَ، وَالتِّرْمِذِيُّ وَصَحَّحَهُ.'),
  ('bulugh_almaram', 844, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 845, 'رَوَاهُ الْخَمْسَةُ، وَصَحَّحَهُ ابْنُ الْمَدِينِيِّ وَالتِّرْمِذِيُّ وَابْنُ حِبَّانَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 846, 'رَوَاهُ إِسْحَاقُ، وَالْبَزَّارُ بِإِسْنَادٍ ضَعِيفٍ.'),
  ('bulugh_almaram', 847, 'مُتَّفَقٌ عَلَيْهِ، وَلِمُسْلِمٍ: رَخَّصَ فِي الْعَرِيَّةِ يَأْخُذُهَا أَهْلُ الْبَيْتِ بِخَرْصِهَا تَمْرًا، يَأْكُلُونَهَا رُطَبًَا.'),
  ('bulugh_almaram', 848, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 849, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 850, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِلْبُخَارِيِّ.'),
  ('bulugh_almaram', 851, 'رَوَاهُ الْخَمْسَةُ إِلَّا النَّسَائِيَّ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 852, 'رَوَاهُ مُسْلِمٌ، وَفِي رِوَايَةٍ لَهُ: أَنَّ النَّبِيَّ - ﷺ - أَمَرَ بِوَضْعِ الْجَوَائِحِ.'),
  ('bulugh_almaram', 853, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 854, 'مُتَّفَقٌ عَلَيْهِ، وَلِلْبُخَارِيِّ: «مَنْ أَسْلَفَ فِي شَيْءٍ».'),
  ('bulugh_almaram', 855, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 856, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 857, 'أَخْرَجَهُ الْحَاكِمُ وَالْبَيْهَقِيُّ، وَرِجَالُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 858, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 859, 'رَوَاهُ الدَّارَقُطْنِيُّ وَالْحَاكِمُ، وَرِجَالهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 860, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 861, 'رَوَاهُ الْحَارِثُ بْنُ أَبِي أُسَامَةَ، وَإِسْنَادُهُ سَاقِطٌ.'),
  ('bulugh_almaram', 864, 'رَوَاهُ أَبُو دَاوُدَ وَمَالِكٌ: مِنْ رِوَايَةِ أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ مُرْسَلًا، بِلَفْظِ: «أَيُّمَا رَجُلٍ بَاعَ مَتَاعًا فَأَفْلَسَ الَّذِي ابْتَاعَهُ، وَلَمْ يَقْبِضِ الَّذِي بَاعَهُ مِنْ ثَمَنِهِ شَيْئًا، فَوَجَدَ مَتَاعَهُ بِعَيْنِهِ، فَهُوَ أَحَقُّ بِهِ، وَإِنْ مَاتَ الْمُشْتَرِي فَصَاحِبُ الْمَتَاعِ أُسْوَةُ الْغُرَمَاءِ».'),
  ('bulugh_almaram', 865, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَعَلَّقَهُ الْبُخَارِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 866, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 867, 'أَخْرَجَهُ أَبُو دَاوُدَ مُرْسَلًا، وَرُجِّحَ.'),
  ('bulugh_almaram', 868, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 869, 'رَوَاهُ الْخَمْسَةُ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 870, 'رَوَاهُ أَحْمَدُ، وَأَصْحَابُ السُّنَنِ إِلَّا التِّرْمِذِيَّ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 871, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 872, 'رَوَاهُ التِّرْمِذِيُّ وَصَحَّحَهُ، وَأَنْكَرُوا عَلَيْهِ; لِأَنَّ رَاوِيَهُ كَثِيرَ بْنَ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عَوْفٍ ضَعِيفٌ، وَكَأَنَّهُ اعْتَبَرَهُ بِكَثْرَةِ طُرُقِهِ.'),
  ('bulugh_almaram', 874, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 875, 'رَوَاهُ ابْنُ حِبَّانَ وَالْحَاكِمُ فِي صَحِيحَيْهِمَا.'),
  ('bulugh_almaram', 876, 'مُتَّفَقٌ عَلَيْهِ، وَفِي رِوَايَةِ أَحْمَدَ: «فَلْيَحْتَلْ».'),
  ('bulugh_almaram', 877, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ وَالنَّسَائِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 878, 'مُتَّفَقٌ عَلَيْهِ، وَفِي رِوَايَةٍ لِلْبُخَارِيِّ: «فَمَنْ مَاتَ وَلَمْ يَتْرُكْ وَفَاءً».'),
  ('bulugh_almaram', 879, 'رَوَاهُ الْبَيْهَقِيُّ بِإِسْنَادٍ ضَعِيفٍ.'),
  ('bulugh_almaram', 880, 'رَوَاهُ أَبُو دَاوُدَ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 881, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ وَابْنُ مَاجَهْ.'),
  ('bulugh_almaram', 882, 'رَوَاهُ النَّسَائِيُّ وَغَيْرُهُ.'),
  ('bulugh_almaram', 883, 'رَوَاهُ أَبُو دَاوُدَ وَصَحَّحَهُ.'),
  ('bulugh_almaram', 884, 'رَوَاهُ الْبُخَارِيُّ فِي أَثْنَاءِ حَدِيثٍ، وَقَدْ تَقَدَّمَ.'),
  ('bulugh_almaram', 885, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 886, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 887, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 889, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 890, 'رَوَاهُ أَبُو دَاوُدَ، وَالتِّرْمِذِيُّ وَحَسَّنَهُ، وَصَحَّحَهُ الْحَاكِمُ، وَاسْتَنْكَرَهُ أَبُو حَاتِمٍ الرَّازِيُّ.'),
  ('bulugh_almaram', 891, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ وَالنَّسَائِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 892, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 894, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 895, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 896, 'رَوَاهُ أَحْمَدُ، وَالْأَرْبَعَةُ إِلَّا النَّسَائِيَّ، وَحَسَّنَهُ التِّرْمِذِيُّ، وَيُقَالُ: إِنَّ الْبُخَارِيَّ ضَعَّفَهُ.'),
  ('bulugh_almaram', 897, 'رَوَاهُ أَبُو دَاوُدَ، وَإِسْنَادُهُ حَسَنٌ.'),
  ('bulugh_almaram', 899, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 900, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِلْبُخَارِيِّ.'),
  ('bulugh_almaram', 901, 'أَخْرَجَهُ الْبُخَارِيُّ، وَفِيهِ قِصَّةٌ.'),
  ('bulugh_almaram', 902, 'رَوَاهُ النَّسَائِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ، وَلَهُ عِلَّةٌ.'),
  ('bulugh_almaram', 903, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَرِجَالُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 904, 'رَوَاهُ ابْنُ مَاجَهْ وَالْبَزَّارُ، وَزَادَ: «وَلَا شُفْعَةَ لِغَائِبٍ». وَإِسْنَادُهُ ضَعِيفٌ.'),
  ('bulugh_almaram', 905, 'رَوَاهُ الدَّارَقُطْنِيُّ، وَرِجَالُهُ ثِقَاتٌ. وَقَالَ مَالِكٌ فِي الْمُوَطَّأِ عَنِ العَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ، عَنْ أَبِيهِ، عَنْ جَدِّهِ: أَنَّهُ عَمِلَ فِي مَالٍ لِعُثْمَانَ عَلَى أَنَّ الرِّبْحَ بَيْنَهُمَا. وَهُوَ مَوْقُوفٌ صَحِيحٌ.'),
  ('bulugh_almaram', 906, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 907, 'مُتَّفَقِ عَلَيْهِ مِنْ إِطْلَاقِ النَّهْيِ عَنْ كِرَاءِ الْأَرْضِ.'),
  ('bulugh_almaram', 908, 'رَوَاهُ مُسْلِمٌ أَيْضًا.'),
  ('bulugh_almaram', 909, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 910, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 911, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 912, 'أَخْرَجَهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 913, 'رَوَاهُ ابْنُ مَاجَهْ.'),
  ('bulugh_almaram', 914, 'رَوَاهُ عَبْدُ الرَّزَّاقِ وَفِيهِ انْقِطَاعٌ، وَوَصَلَهُ الْبَيْهَقِيُّ مِنْ طَرِيقِ أَبِي حَنِيفَةَ.'),
  ('bulugh_almaram', 915, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 916, 'رَوَاهُ الثَّلَاثَةُ، وَحَسَّنَهُ التِّرْمِذِيُّ، وَقَالَ: رُوِيَ مُرْسَلًا.'),
  ('bulugh_almaram', 917, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 918, 'رَوَاهُ أَحْمَدُ وَابْنُ مَاجَهْ.'),
  ('bulugh_almaram', 920, 'رَوَاهُ أَبُو دَاوُدَ، وَصَحَّحَهُ ابْنُ الْجَارُودِ.'),
  ('bulugh_almaram', 921, 'رَوَاهُ ابْنُ مَاجَهْ بِإِسْنَادٍ ضَعِيفٍ.'),
  ('bulugh_almaram', 922, 'رَوَاهُ أَبُو دَاوُدَ وَالتِّرْمِذِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 923, 'رَوَاهُ أَبُو دَاوُدَ، وَفِيهِ ضَعْفٌ.'),
  ('bulugh_almaram', 924, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ، وَرِجَالُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 925, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 926, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 927, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 928, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 929, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 930, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ وَابْنُ حِبَّانَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 931, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 932, 'رَوَاهُ أَحْمَدُ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 933, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 934, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 935, 'رَوَاهُ الْبُخَارِيُّ فِي «الْأَدَبِ الْمُفْرَدِ» وَأَبُو يَعْلَى بِإِسْنَادٍ حَسَنٍ.'),
  ('bulugh_almaram', 936, 'رَوَاهُ الْبَزَّارُ بِإِسْنَادٍ ضَعِيفٍ.'),
  ('bulugh_almaram', 937, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 938, 'رَوَاهُ الْحَاكِمُ وَصَحَّحَهُ، وَالْمَحْفُوظُ مِنْ رِوَايَةِ ابْنِ عُمَرَ، عَنْ عُمَرَ قَوْلُهُ.'),
  ('bulugh_almaram', 939, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 940, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 941, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 942, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ إِلَّا التِّرْمِذِيَّ، وَصَحَّحَهُ ابْنُ خُزَيْمَةَ وَابْنُ الْجَارُودِ وَابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 943, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 944, 'رَوَاهُ أَبُو دَاوُدَ.'),
  ('bulugh_almaram', 945, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 946, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 947, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 948, 'أَخْرَجَهُ الْحَاكِمُ بِلَفْظِ أُسَامَةَ، وَرَوَى النَّسَائِيُّ حَدِيثَ أُسَامَةَ بِهَذَا اللَّفْظِ.'),
  ('bulugh_almaram', 949, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ، وَهُوَ مِنْ رِوَايَةِ الْحَسَنِ الْبَصْرِيِّ عَنْ عِمْرَانَ، وَقِيلَ: إِنَّهُ لَمْ يَسْمَعْ مِنْهُ.'),
  ('bulugh_almaram', 950, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَصَحَّحَهُ ابْنُ خُزَيْمَةَ وَابْنُ الْجَارُودِ، وَقَوَّاهُ ابْنُ عَدِيٍّ.'),
  ('bulugh_almaram', 951, 'أَخْرَجَهُ أَحْمَدُ وَالْأَرْبَعَةُ سِوَى التِّرْمِذِيِّ، وَحَسَّنَهُ أَبُو زُرْعَةَ الرَّازِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 952, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ سِوَى أَبِي دَاوُدَ، وَحَسَّنَهُ التِّرْمِذِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 953, 'رَوَاهُ أَبُو دَاوُدَ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 954, 'رَوَاهُ النَّسَائِيُّ وَالدَّارَقُطْنِيُّ، وَقَوَّاهُ ابْنُ عَبْدِ الْبَرِّ، وَأَعَلَّهُ النَّسَائِيُّ، وَالصَّوَابُ: وَقْفُهُ عَلَى عُمَرَ.'),
  ('bulugh_almaram', 955, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ وَابْنُ مَاجَهْ، وَصَحَّحَهُ ابْنُ الْمَدِينِيِّ وَابْنُ عَبْدِ الْبَرِّ.'),
  ('bulugh_almaram', 956, 'رَوَاهُ الْحَاكِمُ مِنْ طَرِيقِ الشَّافِعِيِّ، عَنْ مُحَمَّدِ بْنِ الْحَسَنِ، عَنْ أَبِي يُوسُفَ، وَصَحَّحَهُ ابْنُ حِبَّانَ، وَأَعَلَّهُ الْبَيْهَقِيُّ.'),
  ('bulugh_almaram', 957, 'أَخْرَجَهُ أَحْمَدُ وَالْأَرْبَعَةُ سِوَى أَبِي دَاوُدَ، وَصَحَّحَهُ التِّرْمِذِيُّ وَابْنُ حِبَّانَ وَالْحَاكِمُ، وَأُعِلَّ بِالْإِرْسَالِ.'),
  ('bulugh_almaram', 958, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 959, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 960, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 961, 'رَوَاهُ أَحْمَدُ، وَالْأَرْبَعَةُ إِلَّا النَّسَائِيَّ، وَحَسَّنَهُ أَحْمَدُ وَالتِّرْمِذِيُّ، وَقَوَّاهُ ابْنُ خُزَيْمَةَ وَابْنُ الْجَارُودِ.'),
  ('bulugh_almaram', 962, 'رَوَاهُ الدَّارَقُطْنِيُّ مِنْ حَدِيثِ ابْنِ عَبَّاسٍ ﵄ وَزَادَ فِي آخِرِهِ: «إِلَّا أَنْ يَشَاءَ الْوَرَثَةُ» وَإِسْنَادُهُ حَسَنٌ.'),
  ('bulugh_almaram', 963, 'رَوَاهُ الدَّارَقُطْنِيُّ.'),
  ('bulugh_almaram', 964, 'أَخْرَجَهُ أَحْمَدُ، وَالْبَزَّارُ مِنْ حَدِيثِ أَبِي الدَّرْدَاءِ.'),
  ('bulugh_almaram', 966, 'أَخْرَجَهُ ابْنُ مَاجَهْ، وَإِسْنَادُهُ ضَعِيفٌ.'),
  ('bulugh_almaram', 967, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 968, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 969, 'رَوَاهُ أَحْمَدُ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 971, 'مُتَّفَقٌ عَلَيْهِ مَعَ بَقِيَّةِ السَّبْعَةِ.'),
  ('bulugh_almaram', 972, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ وَابْنُ خُزَيْمَةَ وَابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 973, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَحَسَّنَهُ التِّرْمِذِيُّ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 974, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ، وَرِجَالُهُ ثِقَاتٌ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 978, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِلْبُخَارِيِّ.'),
  ('bulugh_almaram', 979, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 981, 'رَوَاهُ أَحْمَدُ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 982, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ وَصَحَّحَهُ ابْنُ الْمَدِينِيِّ وَالتِّرْمِذِيُّ وَابْنُ حِبَّانَ، وَأُعِلَّ بِالْإِرْسَالِ.'),
  ('bulugh_almaram', 983, 'أَخْرَجَهُ الْأَرْبَعَةُ إِلَّا النَّسَائِيَّ، وَصَحَّحَهُ أَبُو عَوَانَةَ وَابْنُ حِبَّانَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 984, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 985, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 986, 'رَوَاهُ ابْنُ مَاجَهْ وَالدَّارَقُطْنِيُّ، وَرِجَالُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 987, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 988, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ وَابْنُ مَاجَهْ، وَأُعِلَّ بِالْإِرْسَالِ.'),
  ('bulugh_almaram', 989, 'رَوَاهُ أَحْمَدُ، وَالْأَرْبَعَةُ، وَحَسَّنَهُ التِّرْمِذِيُّ.'),
  ('bulugh_almaram', 990, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ وَالتِّرْمِذِيُّ وَصَحَّحَهُ، وَكَذَلِكَ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 991, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 992, 'رَوَاهُ مُسْلِمٌ، وَفِي رِوَايَةٍ لَهُ: «وَلَا يَخْطُبُ»، وَزَادَ ابْنُ حِبَّانَ: «وَلَا يُخْطَبُ عَلَيْهِ».'),
  ('bulugh_almaram', 993, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 995, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 996, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 997, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 998, 'رَوَاهُ أَحْمَدُ وَالنَّسَائِيُّ، وَالتِّرْمِذِيُّ وَصَحَّحَهُ.'),
  ('bulugh_almaram', 999, 'أَخْرَجَهُ الْأَرْبَعَةُ إِلَّا النَّسَائِيَّ.'),
  ('bulugh_almaram', 1000, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ، وَرِجَالُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 1001, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 1002, 'رَوَاهُ الْحَاكِمُ، وَفِي إِسْنَادِهِ رَاوٍ لَمْ يُسَمَّ، وَاسْتَنْكَرَهُ أَبُو حَاتِمٍ.'),
  ('bulugh_almaram', 1004, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1005, 'رَوَاهُ أَبُو دَاوُدَ، وَالْحَاكِمُ بِسَنَدٍ جَيِّدٍ.'),
  ('bulugh_almaram', 1006, 'مُتَّفَقٌ عَلَيْهِ فِي حَدِيثٍ طَوِيلٍ، وَلِمُسْلِمٍ عَنْهَا: أَنَّ زَوْجَهَا كَانَ عَبْدًا، وَفِي رِوَايَةٍ عَنْهَا: كَانَ حُرًّا، وَالْأَوَّلُ أَثْبَتُ، وَصَحَّ عَنِ ابْنِ عَبَّاسٍ عِنْدَ الْبُخَارِيِّ; أَنَّهُ كَانَ عَبْدًا.'),
  ('bulugh_almaram', 1007, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ إِلَّا النَّسَائِيَّ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالدَّارَقُطْنِيُّ وَالْبَيْهَقِيُّ، وَأَعَلَّهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1008, 'رَوَاهُ أَحْمَدُ وَالتِّرْمِذِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالْحَاكِمُ، وَأَعَلَّهُ الْبُخَارِيُّ وَأَبُو زُرْعَةَ وَأَبُو حَاتِمٍ.'),
  ('bulugh_almaram', 1009, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ إِلَّا النَّسَائِيَّ، وَصَحَّحَهُ أَحْمَدُ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 1011, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ وَابْنُ مَاجَهْ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 1012, 'أَخْرَجَهُ سَعِيدُ بْنُ مَنْصُورٍ، وَمَالِكٌ، وَابْنُ أَبِي شَيْبَةَ، وَرِجَالُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 1013, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ وَاللَّفْظُ لَهُ، وَرِجَالُهُ ثِقَاتٌ، لَكِنْ أُعِلَّ بِالْإِرْسَالِ.'),
  ('bulugh_almaram', 1014, 'رَوَاهُ التِّرْمِذِيُّ وَالنَّسَائِيُّ وَابْنُ حِبَّانَ، وَأُعِلَّ بِالْوَقْفِ.'),
  ('bulugh_almaram', 1015, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِلْبُخَارِيِّ.'),
  ('bulugh_almaram', 1016, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1017, 'أَخْرَجَهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1018, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ وَالنَّسَائِيُّ وَابْنُ مَاجَهْ، وَعَلَّقَ الْبُخَارِيُّ بَعْضَهُ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 1019, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 1020, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1021, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِلْبُخَارِيِّ.'),
  ('bulugh_almaram', 1022, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1023, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1024, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ وَاللَّفْظُ لَهُ، وَالنَّسَائِيُّ وَالطَّحَاوِيُّ، وَرِجَالُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 1025, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1026, 'أَخْرَجَاهُ، وَاللَّفْظُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 1027, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1028, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1029, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 1030, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ إِلَّا التِّرْمِذِيَّ.'),
  ('bulugh_almaram', 1031, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ وَجَمَاعَةٌ.'),
  ('bulugh_almaram', 1032, 'أَخْرَجَهُ أَبُو دَاوُدَ، وَأَشَارَ إِلَى تَرْجِيحِ وَقْفِهِ.'),
  ('bulugh_almaram', 1033, 'أَخْرَجَهُ التِّرْمِذِيُّ وَصَحَّحَهُ، وَخُولِفَ فِي ذَلِكَ.'),
  ('bulugh_almaram', 1034, 'أَخْرَجَهُ الدَّارَقُطْنِيُّ مَوْقُوفًا، وَفِي سَنَدِهِ مَقَالٌ.'),
  ('bulugh_almaram', 1035, 'أَخْرَجَهُ أَبُو دَاوُدَ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 1036, 'أَخْرَجَهُ ابْنُ مَاجَهْ، وَفِي إِسْنَادِهِ رَاوٍ مَتْرُوكٌ.'),
  ('bulugh_almaram', 1038, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 1039, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1040, 'أَخْرَجَهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1041, 'أَخْرَجَهُ مُسْلِمٌ أَيْضًا.'),
  ('bulugh_almaram', 1043, 'رَوَاهُ التِّرْمِذِيُّ وَاسْتَغْرَبَهُ، وَرِجَالُهُ رِجَالُ الصَّحِيحِ.'),
  ('bulugh_almaram', 1045, 'أَخْرَجَهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1046, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِلْبُخَارِيِّ.'),
  ('bulugh_almaram', 1047, 'رَوَاهُ أَبُو دَاوُدَ، وَسَنَدُهُ ضَعِيفٌ.'),
  ('bulugh_almaram', 1048, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1049, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1050, 'رَوَاهُ الْأَرْبَعَةُ، وَهَذَا لَفْظُ النَّسَائِيِّ، وَسَنَدُهُ صَحِيحٌ.'),
  ('bulugh_almaram', 1051, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1052, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1053, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1055, 'رَوَاهُ الْأَرْبَعَةُ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالْحَاكِمُ، وَلَكِنْ رَجَّحَ التِّرْمِذِيُّ إِرْسَالَهُ.'),
  ('bulugh_almaram', 1056, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَسَنَدُهُ صَحِيحٌ.'),
  ('bulugh_almaram', 1057, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِلْبُخَارِيِّ.'),
  ('bulugh_almaram', 1058, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1059, 'مُتَّفَقٌ عَلَيْه.'),
  ('bulugh_almaram', 1060, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ وَاللَّفْظُ لَهُ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 1062, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1063, 'مُتَّفَقٌ عَلَيْهِ.'),
