  ('bulugh_almaram', 1075, 'رَوَاهُ الْأَرْبَعَةُ إِلَّا النَّسَائِيَّ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 1078, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1079, 'رَوَاهُ ابْنُ مَاجَهْ وَالْحَاكِمُ، وَقَالَ أَبُو حَاتِمٍ: لَا يَثْبُتُ.'),
  ('bulugh_almaram', 1080, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1081, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1082, 'رَوَاهُ أَبُو يَعْلَى، وَصَحَّحَهُ الْحَاكِمُ، وَهُوَ مَعْلُولٌ.'),
  ('bulugh_almaram', 1084, 'أَخْرَجَهُ أَبُو دَاوُدَ وَالتِّرْمِذِيُّ وَصَحَّحَهُ، وَنُقِلَ عَنِ البُخَارِيِّ أَنَّهُ أَصَحُّ مَا وَرَدَ فِيهِ.'),
  ('bulugh_almaram', 1085, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ إِلَّا التِّرْمِذِيَّ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 1086, 'رَوَاهُ أَبُو دَاوُدَ هَكَذَا مَوْقُوفًا، وَسَنَدُهُ صَحِيحٌ.'),
  ('bulugh_almaram', 1087, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1088, 'رَوَاهُ التِّرْمِذِيُّ، وَرُوَاتُهُ ثِقَاتٌ.'),
