  ('bulugh_almaram', 1096, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1097, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَرِجَالُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 1098, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1099, 'أَخْرَجَهُ النَّسَائِيُّ مِنْ وَجْهٍ آخَرَ: عَنِ ابْنِ عَبَّاسٍ بِلَفْظٍ قَالَ: «طَلِّقْهَا».'),
  ('bulugh_almaram', 1100, 'أَخْرَجَهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ وَابْنُ مَاجَهْ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 1101, 'أَخْرَجَهُ الْبَيْهَقِيُّ، وَهُوَ حَسَنٌ مَوْقُوفٌ.'),
  ('bulugh_almaram', 1102, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1103, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1104, 'رَوَاهُ ابْنُ مَاجَهْ، وَرُوَاتُهُ ثِقَاتٌ، لَكِنَّهُ مَعْلُولٌ.'),
  ('bulugh_almaram', 1105, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1106, 'مُتَّفَقٌ عَلَيْهِ، وَهَذَا لَفْظُ مُسْلِمٍ.'),
  ('bulugh_almaram', 1107, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَإِسْنَادُهُ حَسَنٌ.'),
  ('bulugh_almaram', 1108, 'مُتَّفَقٌ عَلَيْهِ.'),
