  ('bulugh_almaram', 1110, 'أَخْرَجَهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ والذُّهْلِيُّ وَابْنُ حِبَّانَ وَالْحَاكِمُ وَغَيْرُهُمْ.'),
  ('bulugh_almaram', 1111, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1112, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ وَابْنُ مَاجَهْ، وَصَحَّحَهُ الْحَاكِمُ، وَأَعَلَّهُ الدَّارَقُطْنِيُّ بِالِانْقِطَاعِ.'),
  ('bulugh_almaram', 1113, 'أَخْرَجَهُ مَالِكٌ فِي قِصَّةٍ بِسَنَدٍ صَحِيحٍ.'),
  ('bulugh_almaram', 1114, 'أَخْرَجَهُ مَرْفُوعًا وَضَعَّفَهُ.'),
  ('bulugh_almaram', 1115, 'أَخْرَجَهُ أَبُو دَاوُدَ وَالتِّرْمِذِيُّ وَابْنُ مَاجَهْ: مِنْ حَدِيثِ عَائِشَةَ، وَصَحَّحَهُ الْحَاكِمُ، وَخَالَفُوهُ، فَاتَّفَقُوا عَلَى ضَعْفِهِ.'),
  ('bulugh_almaram', 1116, 'أَخْرَجَهُ أَبُو دَاوُدَ وَالتِّرْمِذِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ، وَحَسَّنَهُ الْبَزَّارُ.'),
  ('bulugh_almaram', 1117, 'أَخْرَجَهُ مَالِكٌ وَالشَّافِعِيُّ.'),
  ('bulugh_almaram', 1118, 'أَخْرَجَهُ الدَّارَقُطْنِيُّ بِإِسْنَادٍ ضَعِيفٍ.'),
  ('bulugh_almaram', 1119, 'أَخْرَجَهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1120, 'أَخْرَجَهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1121, 'أَخْرَجَهُ أَبُو دَاوُدَ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 1123, 'مُتَّفَقٌ عَلَيْهِ مِنْ حَدِيثِهِ.'),
  ('bulugh_almaram', 1127, 'أَخْرَجَهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1128, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1129, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1130, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1131, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1132, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1133, 'رَوَاهُ التِّرْمِذِيُّ وَصَحَّحَهُ هُوَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 1134, 'رَوَاهُ الدَّارَقُطْنِيُّ وَابْنُ عَدِيٍّ مَرْفُوعًا وَمَوْقُوفًا، وَرَجَّحَا الْمَوْقُوفَ.'),
  ('bulugh_almaram', 1135, 'رَوَاهُ أَبُو دَاوُدَ.'),
  ('bulugh_almaram', 1136, 'أَخْرَجَهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1137, 'أَخْرَجَهُ أَبُو دَاوُدَ وَهُوَ مُرْسَلٌ، وَلَيْسَتْ لِزِيَادٍ صُحْبَةٌ.'),
  ('bulugh_almaram', 1138, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1139, 'رَوَاهُ النَّسَائِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَالدَّارَقُطْنِيُّ.'),
  ('bulugh_almaram', 1140, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1142, 'أَخْرَجَهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1143, 'رَوَاهُ النَّسَائِيُّ، وَهُوَ عِنْدَ مُسْلِمٍ بِلَفْظِ: «أَنْ يَحْبِسَ عَمَّنْ يَمْلِكُ قُوتَهُ».'),
  ('bulugh_almaram', 1144, 'أَخْرَجَهُ الْبَيْهَقِيُّ، وَرِجَالُهُ ثِقَاتٌ، لَكِنْ قَالَ: الْمَحْفُوظُ وَقْفُهُ.'),
  ('bulugh_almaram', 1145, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1146, 'رَوَاهُ الدَّارَقُطْنِيُّ، وَإِسْنَادُهُ حَسَنٌ.'),
  ('bulugh_almaram', 1147, 'أَخْرَجَهُ سَعِيدُ بْنُ مَنْصُورٍ: عَنْ سُفْيَانَ، عَنْ أَبِي الزِّنَادِ، عَنْهُ.'),
  ('bulugh_almaram', 1148, 'أَخْرَجَهُ الشَّافِعِيُّ، ثُمَّ الْبَيْهَقِيُّ بِإِسْنَادٍ حَسَنٍ.'),
  ('bulugh_almaram', 1149, 'أَخْرَجَهُ النَّسَائِيُّ وَالْحَاكِمُ بِتَقْدِيمِ الزَّوْجَةِ عَلَى الْوَلَدِ.'),
  ('bulugh_almaram', 1150, 'أَخْرَجَهُ أَبُو دَاوُدَ، وَالتِّرْمِذِيُّ وَحُسَّنَهُ.'),
  ('bulugh_almaram', 1151, 'رَوَاهُ أَحْمَدُ وَأَبُو دَاوُدَ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 1152, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ.'),
  ('bulugh_almaram', 1153, 'أَخْرَجَهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 1154, 'أَخْرَجَهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1155, 'أَخْرَجَهُ أَحْمَدُ مِنْ حَدِيثِ عَلِيٍّ فَقَالَ: «وَالْجَارِيَةُ عِنْدَ خَالَتِهَا، فَإِنَّ الْخَالَةَ وَالِدَةٌ».'),
  ('bulugh_almaram', 1156, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِلْبُخَارِيِّ.'),
  ('bulugh_almaram', 1157, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1158, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1159, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 1160, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1161, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَحَسَّنَهُ التِّرْمِذِيُّ، وَهُوَ مِنْ رِوَايَةِ الْحَسَنِ الْبَصْرِيِّ عَنْ سَمُرَةَ، وَقَدِ اخْتُلِفَ فِي سَمَاعِهِ مِنْهُ.'),
  ('bulugh_almaram', 1162, 'رَوَاهُ أَحْمَدُ وَالتِّرْمِذِيُّ وَابْنُ مَاجَهْ، وَصَحَّحَهُ ابْنُ الْجَارُودِ وَالْبَيْهَقِيُّ، وَقَالَ التِّرْمِذِيُّ: إِنَّهُ مُضْطَرِبٌ.'),
  ('bulugh_almaram', 1163, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1164, 'أَخْرَجَهُ أَحْمَدُ وَأَبُو دَاوُدَ وَالنَّسَائِيُّ: مِنْ وَجْهٍ آخَرَ عَنْ عَلِيٍّ، وَقَالَ فِيهِ: «الْمُؤْمِنُونَ تَتَكَافَأُ دِمَاؤُهُمْ، وَيَسْعَى بِذِمَّتِهِمْ أَدْنَاهُمْ، وَهُمْ يَدٌ عَلَى مَنْ سِوَاهُمْ، وَلَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ، وَلَا ذُو عَهْدٍ فِي عَهْدِهِ» وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 1165, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 1166, 'رَوَاهُ أَحْمَدُ وَالثَّلَاثَةُ بِإِسْنَادٍ صَحِيحٍ.'),
  ('bulugh_almaram', 1167, 'رَوَاهُ أَحْمَدُ وَالدَّارَقُطْنِيُّ، وَأُعِلَّ بِالْإِرْسَالِ.'),
  ('bulugh_almaram', 1168, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1169, 'أَخْرَجَهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ: مِنْ حَدِيثِ ابْنِ عَبَّاسٍ، أَنَّ عُمَرَ - ﵁ - سَأَلَ مَنْ شَهِدَ قَضَاءَ رَسُولِ اللَّهِ - ﷺ - فِي الْجَنِينِ، قَالَ: فَقَامَ حَمَلُ بْنُ النَّابِغَةِ، فَقَالَ: كُنْتُ بَيْنَ امْرَأَتَيْنِ، فَضَرَبَتْ إِحْدَاهُمَا الْأُخْرَى...'),
  ('bulugh_almaram', 1170, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِلْبُخَارِيِّ.'),
  ('bulugh_almaram', 1171, 'أَخْرَجَهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ وَابْنُ مَاجَهْ بِإِسْنَادٍ قَوِيٍّ.'),
  ('bulugh_almaram', 1172, 'رَوَاهُ الدَّارَقُطْنِيُّ مَوْصُولًا وَمُرْسَلًا، وَصَحَّحَهُ ابْنُ الْقَطَّانِ، وَرِجَالُهُ ثِقَاتٌ، إِلَّا أَنَّ الْبَيْهَقِيَّ رَجَّحَ الْمُرْسَلَ.'),
  ('bulugh_almaram', 1173, 'أَخْرَجَهُ عَبْدُ الرَّزَّاقِ هَكَذَا مُرْسَلًا.'),
  ('bulugh_almaram', 1174, 'أَخْرَجَهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1175, 'أَخْرَجَهُ أَبُو دَاوُدَ، وَالنَّسَائِيُّ.'),
  ('bulugh_almaram', 1177, 'أَخْرَجَهُ أَبُو دَاوُدَ فِي «الْمَرَاسِيلِ»، وَالنَّسَائِيُّ وَابْنُ خُزَيْمَةَ وَابْنُ الْجَارُودِ وَابْنُ حِبَّانَ وَأَحْمَدُ، وَاخْتَلَفُوا فِي صِحَّتِهِ.'),
  ('bulugh_almaram', 1178, 'أَخْرَجَهُ ابْنُ أَبِي شَيْبَةَ مِنْ وَجْهٍ آخَرَ مَوْقُوفًا، وَهُوَ أَصَحُّ مِنَ المرْفُوعِ.'),
  ('bulugh_almaram', 1179, 'أَخْرَجَهُ أَبُو دَاوُدَ وَالتِّرْمِذِيُّ: مِنْ طَرِيقِ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ رَفَعَهُ: «الدِّيَةُ ثَلَاثُونَ حِقَّةً، وَثَلَاثُونَ جَذَعَةً، وَأَرْبَعُونَ خَلِفَةً فِي بُطُونِهَا أَوْلَادُهَا».'),
  ('bulugh_almaram', 1180, 'أَخْرَجَهُ ابْنُ حِبَّانَ فِي حَدِيثٍ صَحَّحَهُ.'),
  ('bulugh_almaram', 1182, 'أَخْرَجَهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ وَابْنُ مَاجَهْ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 1183, 'رَوَاهُ الْبُخَارِيُّ، وَلِأَبِي دَاوُدَ وَالتِّرْمِذِيِّ: «الْأَصَابِعُ سَوَاءٌ، وَالْأَسْنَانُ سَوَاءٌ: الثَّنِيَّةُ وَالضِّرْسُ سَوَاءٌ»، وَلِابْنِ حِبَّانَ: «دِيَةُ أَصَابِعِ الْيَدَيْنِ وَالرِّجْلَيْنِ سَوَاءٌ، عَشَرَةٌ مِنَ الْإِبِلِ لِكُلِّ إصْبَعٍ».'),
  ('bulugh_almaram', 1184, 'أَخْرَجَهُ الدَّارَقُطْنِيُّ، وَصَحَّحَهُ الْحَاكِمُ، وَهُوَ عِنْدَ أَبِي دَاوُدَ وَالنَّسَائِيِّ وَغَيْرِهِمَا; إِلَّا أَنَّ مَنْ أَرْسَلَهُ أَقْوَى مِمَّنْ وَصَلَهُ.'),
  ('bulugh_almaram', 1185, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَزَادَ أَحْمَدُ: «وَالْأَصَابِعُ سَوَاءٌ، كُلُّهُنَّ عَشْرٌ عَشْرٌ مِنَ الْإِبِلِ» وَصَحَّحَهُ ابْنُ خُزَيْمَةَ وَابْنُ الْجَارُودِ.'),
  ('bulugh_almaram', 1186, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَلَفْظُ أَبِي دَاوُدَ: «دِيَةُ الْمُعَاهِدِ نِصْفُ دِيَةِ الْحُرِّ»، وَلِلنَّسَائِيِّ: «عَقْلُ الْمَرْأَةِ مِثْلُ عَقْلِ الرَّجُلِ، حَتَّى يَبْلُغَ الثُّلُثَ مِنْ دِيَتِهَا» وَصَحَّحَهُ ابْنُ خُزَيْمَةَ.'),
  ('bulugh_almaram', 1187, 'أَخْرَجَهُ الدَّارَقُطْنِيُّ وَضَعَّفَهُ.'),
  ('bulugh_almaram', 1188, 'رَوَاهُ الْأَرْبَعَةُ، وَرَجَّحَ النَّسَائِيُّ وَأَبُو حَاتِمٍ إِرْسَالَهُ.'),
  ('bulugh_almaram', 1189, 'رَوَاهُ النَّسَائِيُّ وَأَبُو دَاوُدَ، وَصَحَّحَهُ ابْنُ خُزَيْمَةَ وَابْنُ الْجَارُودِ.'),
  ('bulugh_almaram', 1190, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1191, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1192, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1193, 'أَخْرَجَهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1194, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1195, 'رَوَاهُ الْبَزَّارُ والْحَاكِمُ وَصَحَّحَهُ فَوَهِمَ; فَإِنَّ فِي إِسْنَادِهِ كَوْثَرَ بْنَ حَكِيمٍ، وَهُوَ مَتْرُوكٌ.'),
  ('bulugh_almaram', 1196, 'أَخْرَجَهُ ابْنُ أَبِي شَيْبَةَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 1197, 'أَخْرَجَهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1198, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَالتِّرْمِذِيُّ وَصَحَّحَهُ.'),
  ('bulugh_almaram', 1199, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 1200, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1201, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ إِلَّا التِّرْمِذِيَّ، وَصَحَّحَهُ ابْنُ حِبَّانَ وَفِي إِسْنَادِهِ اخْتِلَافٌ.'),
  ('bulugh_almaram', 1202, 'مُتَّفَقٌ عَلَيْهِ، وَفِي رِوَايَةٍ لِأَبِي دَاوُدَ: وَكَانَ قَدِ اسْتُتِيبَ قَبْلَ ذَلِكَ.'),
  ('bulugh_almaram', 1203, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1204, 'رَوَاهُ أَبُو دَاوُدَ وَرُوَاتُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 1205, 'مُتَّفَقٌ عَلَيْهِ، وَهَذَا اللَّفْظُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 1206, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1207, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1208, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1209, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1210, 'مُتَّفَقٌ عَلَيْهِ، وَهَذَا لَفْظُ مُسْلِمٍ.'),
  ('bulugh_almaram', 1211, 'رَوَاهُ أَبُو دَاوُدَ، وَهُوَ فِي مُسْلِمٍ مَوْقُوفٌ.'),
  ('bulugh_almaram', 1212, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1213, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1215, 'رَوَاهُ أَحْمَدُ وَالنَّسَائِيُّ وَابْنُ مَاجَهْ، وَإِسْنَادُهُ حَسَنٌ.'),
  ('bulugh_almaram', 1216, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَرِجَالُهُ مُوَثَّقُونَ، إِلَّا أَنَّ فِيهِ اخْتِلَافًا.'),
  ('bulugh_almaram', 1217, 'رَوَاهُ التِّرْمِذِيُّ وَرِجَالُهُ ثِقَاتٌ، إِلَّا أَنَّهُ اخْتُلِفَ فِي رَفْعِهِ وَوَقْفِهِ.'),
  ('bulugh_almaram', 1218, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1219, 'أَخْرَجَهُ ابْنُ مَاجَهْ، وَإِسْنَادُهُ ضَعِيفٌ.'),
  ('bulugh_almaram', 1220, 'أَخْرَجَهُ التِّرْمِذِيُّ، وَالْحَاكِمُ: مِنْ حَدِيثِ عَائِشَةَ ﵂ بِلَفْظِ: «ادْرَأُوا الْحُدُودَ عَنِ الْمُسْلِمِينَ مَا اسْتَطَعْتُمْ».'),
  ('bulugh_almaram', 1221, 'رَوَاهُ الْبَيْهَقِيُّ: عَنْ عَلِيٍّ - ﵁ - مِنْ قَوْلِهِ بِلَفْظِ: «ادْرَأُوا الْحُدُودَ بِالشُّبُهَاتِ».'),
  ('bulugh_almaram', 1222, 'رَوَاهُ الْحَاكِمُ، وَهُوَ فِي «الْمُوَطَّإِ» مِنْ مُرْسَلِ زَيْدِ بْنِ أَسْلَمَ.'),
  ('bulugh_almaram', 1223, 'أَخْرَجَهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَأَشَارَ إِلَيْهِ البُخَارِيُّ.'),
  ('bulugh_almaram', 1224, 'أَخْرَجَهُ أَبُو يَعْلَى، وَرِجَالُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 1226, 'رَوَاهُ مَالِكٌ، وَالثَّوْرِيُّ فِي «جَامِعِهِ».'),
  ('bulugh_almaram', 1227, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1228, 'مُتَّفَقٌ عَلَيْهِ. وَاللَّفْظُ لِمُسْلِم.'),
  ('bulugh_almaram', 1229, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1230, 'مُتَّفَقٌ عَلَيْهِ أَيْضًا.'),
  ('bulugh_almaram', 1231, 'مُتَّفَقٌ عَلَيْهِ، وَاللَّفْظُ لِمُسْلِمٍ.'),
  ('bulugh_almaram', 1232, 'رَوَاهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ وَابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 1233, 'رَوَاهُ الْمَذْكُورُونَ، وَصَحَّحَهُ أَيْضًا التِّرْمِذِيُّ وَابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 1234, 'أَخْرَجَهُ أَبُو دَاوُدَ وَاللَّفْظُ لَهُ، وَأَحْمَدُ وَالنَّسَائِيُّ، وَرِجَالُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 1235, 'أَخْرَجَهُ الْبَزَّارُ أَيْضًا، وَقَالَ: لَا بَأْسَ بِإِسْنَادِهِ.'),
  ('bulugh_almaram', 1236, 'رَوَاهُ النَّسَائِيُّ وَبَيَّنَ أَنَّهُ مُنْقَطِعٌ، وَقَالَ أَبُو حَاتِمٍ: هُوَ مُنْكَرٌ.'),
  ('bulugh_almaram', 1237, 'أَخْرَجَهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 1238, 'أَخْرَجَهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَصَحَّحَهُ ابْنُ الْجَارُودِ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 1239, 'أَخْرَجَهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ وَاسْتَنْكَرَهُ.'),
  ('bulugh_almaram', 1241, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1243, 'أَخْرَجَهُ أَحْمَدُ وَهَذَا لَفْظُهُ، وَالْأَرْبَعَةُ.'),
  ('bulugh_almaram', 1244, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1245, 'رَوَاهُ التِّرْمِذِيُّ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 1246, 'أَخْرَجَهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1247, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1248, 'أَخْرَجَهُ مُسْلِمُ.'),
  ('bulugh_almaram', 1249, 'أَخْرَجَهُ أَحْمَدُ وَالْأَرْبَعَةُ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 1250, 'أَخْرَجَهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1251, 'أَخْرَجَهُ الْبَيْهَقِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 1252, 'أَخْرَجَهُ مُسْلِمٌ وَأَبُو دَاوُدَ وَغَيْرُهُمَا.'),
  ('bulugh_almaram', 1253, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1254, 'رَوَاهُ أَبُو دَاوُدَ وَالنَّسَائِيُّ.'),
  ('bulugh_almaram', 1255, 'أَخْرَجَهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1256, 'رَوَاهُ الْأَرْبَعَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ.'),
  ('bulugh_almaram', 1257, 'أَخْرَجَهُ ابْنُ أَبِي خَيْثَمَةَ وَالدَّارَقُطْنِيُّ.'),
  ('bulugh_almaram', 1259, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1260, 'رَوَاهُ أَحْمَدُ وَالنَّسَائِيُّ، وَصَحَّحَهُ الْحَاكِمُ.'),
  ('bulugh_almaram', 1261, 'رَوَاهُ ابْنُ مَاجَه، وَأَصْلُهُ فِي الْبُخَارِيِّ.'),
  ('bulugh_almaram', 1262, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1264, 'رَوَاهُ الثَّلَاثَةُ وَإِسْنَادُهُ صَحِيحٌ، وَرَجَّحَ الْبُخَارِيُّ إِرْسَالَهُ.'),
  ('bulugh_almaram', 1265, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1266, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1267, 'رَوَاهُ النَّسَائِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 1268, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1269, 'أَخْرَجَهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1270, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1271, 'رَوَاهُ أَحْمَدُ وَالثَّلَاثَةُ، وَصَحَّحَهُ الْحَاكِمُ، وَأَصْلُهُ فِي الْبُخَارِيِّ.'),
  ('bulugh_almaram', 1272, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1273, 'رَوَاهُ مُسْلِمٌ.'),
  ('bulugh_almaram', 1274, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1275, 'رَوَاهُ أَبُو دَاوُدَ، وَصَحَّحَهُ التِّرْمِذِيُّ.'),
  ('bulugh_almaram', 1276, 'أَخْرَجَهُ أَبُو دَاوُدَ مُطَوَّلًا.'),
  ('bulugh_almaram', 1277, 'رَوَاهُ الثَّلَاثَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ وَابْنُ حِبَّانَ وَالْحَاكِمُ.'),
  ('bulugh_almaram', 1278, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1279, 'رَوَاهُ أَحْمَدُ وَالنَّسَائِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 1280, 'رَوَاهُ أَبُو دَاوُدَ، وَأَصْلُهُ عِنْدَ مُسْلِمٍ.'),
  ('bulugh_almaram', 1281, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1282, 'أَخْرَجَهُ أَبُو دَاوُدَ فِي «الْمَرَاسِيلِ» وَرِجَالُهُ ثِقَاتٌ، وَوَصَلَهُ الْعُقَيْلِيُّ بِإِسْنَادٍ ضَعِيفٍ عَنْ عَلِيٍّ - ﵁ -.'),
  ('bulugh_almaram', 1283, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1284, 'أَخْرَجَهُ أَبُو دَاوُدَ فِي «الْمَرَاسِيلِ» وَرِجَالُهُ ثِقَاتٌ.'),
  ('bulugh_almaram', 1285, 'أَخْرَجَهُ التِّرْمِذِيُّ وَصَحَّحَهُ، وَأَصْلُهُ عِنْدَ مُسْلِمٍ.'),
  ('bulugh_almaram', 1286, 'أَخْرَجَهُ أَبُو دَاوُدَ، وَرِجَالُهُ مُوَثَّقُونَ.'),
  ('bulugh_almaram', 1287, 'رَوَاهُ الْبُخَارِيُّ.'),
