  ('bulugh_almaram', 1332, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1333, 'مُتَّفَقٌ عَلَيْهِ، وَهَذَا لَفْظُ مُسْلِمٍ.'),
