  ('bulugh_almaram', 1343, 'رَوَاهُ أَحْمَدُ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 1344, 'أَخْرَجَهُ عَبْدُ الرَّزَّاقِ بِإِسْنَادٍ صَحِيحٍ إِلَى ابْنِ عَبَّاسٍ، مَوْقُوفًا عَلَيْهِ.'),
  ('bulugh_almaram', 1346, 'مُتَّفَقٌ عَلَيْهِ، وَفِي لَفْظٍ: سَمِينَيْنِ، وَلِأَبِي عَوَانَةَ فِي «صَحِيحِهِ»: ثَمِينَيْنِ، بِالْمُثَلَّثَةِ بَدَلَ السِّينِ، وَفِي لَفْظٍ لِمُسْلِمٍ: وَيَقُولُ: «بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ».'),
  ('bulugh_almaram', 1348, 'رَوَاهُ أَحْمَدُ وَابْنُ مَاجَه، وَصَحَّحَهُ الْحَاكِمُ، لَكِنْ رَجَّحَ الْأَئِمَّةُ غَيْرُهُ وَقْفَهُ.'),
  ('bulugh_almaram', 1349, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1350, 'رَوَاهُ الْخَمْسَةُ، وَصَحَّحَهُ التِّرْمِذِيُّ وَابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 1351, 'رَوَاهُ مُسْلِمٌ.'),
