  ('bulugh_almaram', 1363, 'مُتَّفَقٌ عَلَيْهِ، وَفِي لَفْظٍ لِلْبُخَارِيِّ: «فَائِت الَّذِي هُوَ خَيْرٌ، وَكَفِّرْ عَنْ يَمِينِكَ»، وَفِي رِوَايَةٍ لِأَبِي دَاوُدَ: «فَكَفِّرْ عَنْ يَمِينِكَ، ثُمَّ ائْتِ الَّذِي هُوَ خَيْرٌ» وَإِسْنَادُهَا صَحِيحٌ.'),
  ('bulugh_almaram', 1364, 'رَوَاهُ الْخَمْسَةُ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 1365, 'رَوَاهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1366, 'أَخْرَجَهُ الْبُخَارِيُّ.'),
  ('bulugh_almaram', 1367, 'أَخْرَجَهُ الْبُخَارِيُّ، وَأَوْرَدَهُ أَبُو دَاوُدَ مَرْفُوعًا.'),
  ('bulugh_almaram', 1368, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1369, 'أَخْرَجَهُ التِّرْمِذِيُّ، وَصَحَّحَهُ ابْنُ حِبَّانَ.'),
