  ('bulugh_almaram', 1390, 'مُتَّفَقٌ عَلَيْهِ.'),
  ('bulugh_almaram', 1391, 'رَوَاهُ ابْنُ حِبَّانَ.'),
  ('bulugh_almaram', 1394, 'أَخْرَجَهُ البَيْهَقِيُّ، وَلَفْظُهُ: «فِي تَمْرَةٍ».'),
  ('bulugh_almaram', 1395, 'رَوَاهُ البُخَارِيُّ.'),
