  ('umdat_alahkam', 340, 'أَخْرَجَهُ الجَمَاعَةُ.'),
  ('umdat_alahkam', 397, 'أَخْرَجَهُ مُسْلِمٌ.'),
  ('umdat_alahkam', 398, 'أَخْرَجَهُ البُخَارِيُّ.')
) as v(slug, number, grading)
join content.hadith_collections c on c.slug = v.slug
where e.collection_id = c.id
  and e.app_id = c.app_id
  and e.number = v.number
  and e.grading is distinct from v.grading;
